-- Seed: Indicadores de 3ro de Secundaria - Inglés

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC1', 'IL-1', 'Responde de forma adecuada a preguntas e indicaciones, a partir de la escucha y lectura de textos breves y sencillos cuya finalidad es dar explicaciones, opinar, sugerir, hacer prohibiciones y advertencias, dar instrucciones, dar noticias, narrar, inferir, predecir y comparar el pasado con el presente, siempre que se le hable de forma pausada y clara.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC1', 'IL-2', 'Produce una serie de frases y oraciones enlazadas por conectores sencillos, aunque con pausas y reformulaciones en lo oral y algunos errores básicos en lo escrito, con la intención de dar explicaciones, opinar, sugerir, hacer prohibiciones y advertencias, dar instrucciones, dar noticias, narrar, inferir, predecir y comparar el pasado con el presente.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC1', 'IL-3', 'Interactúa oralmente y por escrito de forma breve y sencilla, con una creciente cantidad de vocabulario variado contenido en una serie de frases y oraciones sencillas enlazadas con conectores, en situaciones de comunicación donde debe dar explicaciones, opinar, sugerir, hacer prohibiciones y advertencias, dar instrucciones, dar noticias, narrar, inferir, predecir y comparar el pasado con el presente.'),

-- BC2
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-4', 'Responde de forma adecuada a preguntas, indicaciones y sus propios análisis, a partir de la escucha o lectura de textos breves y sencillos referentes a temas que le son familiares.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-5', 'Presenta información, ideas, análisis y puntos de vista sobre su contexto inmediato y situaciones cotidianas de forma creativa y crítica, en textos breves y sencillos que produce con la estructura lógico-verbal adecuada al contenido, el tipo de texto y la situación.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-6', 'Interactúa en forma oral o escrita a través de una serie de oraciones breves y sencillas secuenciadas de una forma lógica y presentadas de forma creativa en diferentes tipos de interacciones donde comparte información y puntos de vista sobre sí mismo y otros, su entorno cotidiano y temas que le son familiares.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-7', 'Responde de forma adecuada a preguntas e indicaciones sobre situaciones y problemas de su entorno inmediato, a partir de textos orales y escritos breves donde se comparte información y puntos de vista detallados sobre los mismos.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-8', 'Se expresa mediante textos orales y escritos para describir con suficiente nivel de detalle, problemas inmediatos propios, de otras personas y del entorno cotidiano, así como para presentar información y puntos de vista pertinentes frente a la situación planteada.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-9', 'Interactúa de forma oral y escrita para solicitar o proveer información y puntos de vista con suficiente detalle sobre situaciones y problemas relativos a actividades cotidianas y de su entorno inmediato, utilizando frases y oraciones breves.'),

-- BC3
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-13', 'Localiza y sistematiza información a partir de la lectura o escucha de información contenida en temas científicos y tecnológicos relativos a su entorno inmediato, siempre que traten temas que le son familiares.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-14', 'Expresa ideas e información y puntos de vista sobre temas científicos, tecnológicos y de otra índole, de forma presencial o virtual, utilizando vocabulario de uso común y oraciones orales o escritas.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-15', 'Interactúa en forma oral o escrita con el propósito de compartir información sobre temas científicos, tecnológicos y de otra índole, de forma presencial o virtual, utilizando vocabulario de uso común.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-16', 'Reconoce las orientaciones relativas a mantener estilos de vida saludables y cuidado del medioambiente, a partir de la información contenida en textos orales y escritos compuestos.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-17', 'Ofrece información y puntos de vista sobre estilos de vida saludables y cuidado del medio ambiente tanto en forma oral como escrita, utilizando frases y oraciones breves y sencillas.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-18', 'Interactúa en forma oral o escrita en situaciones donde se brinda información y puntos de vista relativas a estilos de vida saludables y cuidado del medioambiente, usando el vocabulario indicado.'),

-- BC4
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-10', 'Interactúa de forma directa y sencilla en el idioma inglés, con cortesía y respeto.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-11', 'Compara las diferencias individuales y la identidad social y cultural propia y de otros países, relativas a señales de advertencia, cuidado del medioambiente, leyendas y tradiciones.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-12', 'Expresa explicaciones y motivos ante situaciones que no le permiten participar de su labor, empleando frases y oraciones sencillas.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-19', 'Se comunica con asertividad, respetando los puntos de vista que ofrecen las demás personas.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-20', 'Trabaja en equipo de forma colaborativa, mostrando empatía, actitud de escucha y colaboración en las tareas que se emprenden.'),
('3ro', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-21', 'Interactúa con cortesía y respeto ante informaciones y puntos de vista que expresan los demás.');
